<?php require_once __DIR__.'/includes/bootstrap.php';require_role(['admin','librarian']);$id=(int)($_GET['id']??0);$b=['title'=>'','author'=>'','isbn'=>'','publisher'=>'','published_year'=>'','category_id'=>'','total_copies'=>1,'description'=>''];if($id){$s=$conn->prepare('SELECT * FROM books WHERE id=? AND is_archived=0');$s->bind_param('i',$id);$s->execute();$b=$s->get_result()->fetch_assoc();if(!$b){flash('error','Book not found.');redirect('books.php');}}$cats=$conn->query('SELECT id,name FROM categories ORDER BY name');page_header($id?'Edit book':'Add book');?><div class="panel form-panel"><h1><?=$id?'Edit book':'Add a book'?></h1><form method="post" action="actions/book_save.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Title *</label><input name="title" required maxlength="200" value="<?=e($b['title'])?>"><label>Author *</label><input name="author" required maxlength="160" value="<?=e($b['author'])?>"><div class="form-grid"><div><label>ISBN</label><input name="isbn" maxlength="30" value="<?=e($b['isbn']??'')?>"></div><div><label>Publisher</label><input name="publisher" value="<?=e($b['publisher']??'')?>"></div><div><label>Published year</label><input type="number" name="published_year" min="1000" max="2100" value="<?=e($b['published_year']??'')?>"></div><div><label>Category</label><select name="category_id"><option value="">No category</option><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=(string)$b['category_id']===(string)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endwhile;?></select></div><div><label>Total copies *</label><input type="number" name="total_copies" min="0" required value="<?=e($b['total_copies'])?>"></div></div><label>Description</label><textarea name="description" rows="4"><?=e($b['description']??'')?></textarea><button class="btn">Save book</button> <a class="btn secondary" href="books.php">Cancel</a></form></div><?php page_footer();?>